public class JPA {
  private static final String DEFAULT = "default";

  /**
   * Run a block of code with the EntityManager for the named Persistence Unit.
   *
   * @param name The persistence unit name
   * @param readOnly Is the transaction read-only?
   * @param block Block of code to execute
   * @param <T> type of result
   * @return code execution result
   */
  public static <T> T transaction(JPAApi jpa, String name, boolean readOnly,
      Function<EntityManager, T> block) {
    EntityManager entityManager = null;
    EntityTransaction tx = null;

    try {
      entityManager = jpa.em(name);

      if (entityManager == null) {
        throw new RuntimeException("No JPA entity manager defined for '" + name + "'");
      }
      if (!readOnly) {
        tx = entityManager.getTransaction();
        tx.begin();
      }

      T result = block.apply(entityManager);

      if (tx != null) {
        if (tx.getRollbackOnly()) {
          tx.rollback();
        } else {
          tx.commit();
        }
      }

      return result;
    } catch (Throwable t) {
      if (tx != null) {
        try {
          tx.rollback();
        } catch (Throwable e) {
        }
      }
      throw t;
    } finally {
      if (entityManager != null) {
        entityManager.close();
      }
    }
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param block Block of code to execute
   */
  public static <T> T transaction(final JPAApi jpa, String name,
      Function<EntityManager, T> block) {
    return transaction(jpa, name, false, block);
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param block Block of code to execute
   */
  public static <T> T transaction(final JPAApi jpa, boolean readOnly,
      Function<EntityManager, T> block) {
    return transaction(jpa, DEFAULT, readOnly, block);
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param block Block of code to execute
   */
  public static <T> T transaction(final JPAApi jpa, Function<EntityManager, T> block) {
    return transaction(jpa, DEFAULT, false, block);
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param callback Block of code to execute
   */
  public static void withTransaction(final JPAApi jpa, final Callback<EntityManager> callback) {
    withTransaction(jpa, DEFAULT, false, callback);
  }


  public static void withTransaction(final JPAApi jpa, String name,
      final Callback<EntityManager> callback) {
    withTransaction(jpa, name, false, callback);
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param callback Block of code to execute
   */
  public static void withTransaction(final JPAApi jpa, boolean readOnly,
      final Callback<EntityManager> callback) {
    withTransaction(jpa, DEFAULT, readOnly, callback);
  }

  /**
   * Run a block of code in a JPA transaction.
   *
   * @param callback Block of code to execute
   */
  public static void withTransaction(final JPAApi jpa, String name, boolean readOnly,
      final Callback<EntityManager> callback) {
    try {
      transaction(jpa, name, readOnly, em -> {
        callback.invoke(em);
        return null;
      });
    } catch (Throwable t) {
      throw new RuntimeException("JPA transaction failed", t);
    }
  }

  public static interface Callback<A> {
    public void invoke(A a);
  }
}
```

